const input=$input.first().json;
if($input.all().length!==1)throw Error('one_request_required');
const hasId=input.insertionId!==undefined&&input.insertionId!==null&&Number(input.insertionId)!==0;
if(hasId){
 const id=Number(input.insertionId),revision=String(input.revision||'');
 if(!Number.isSafeInteger(id)||id<=0||!/^[A-Za-z0-9_-]{1,128}$/.test(revision)||input.cursor)throw Error('invalid_preview_identity');
 return [{json:{mode:'single',insertionId:id,revision,path:'/api/insertions/'+id+'/visual-previews/'+revision},pairedItem:{item:0}}];
}
if(input.revision)throw Error('insertion_required');
const cursor=String(input.cursor||'0');
if(!/^\d{1,19}$/.test(cursor)||BigInt(cursor)>9223372036854775807n)throw Error('invalid_cursor');
return [{json:{mode:'feed',cursor,path:'/api/visual-previews/completed?cursor='+cursor},pairedItem:{item:0}}];

const request=$('Validate preview request').first().json,response=$input.first().json;
let items,nextCursor=null;
if(request.mode==='feed'){
 if(!Array.isArray(response.items)||response.items.length>50||!/^\d{1,19}$/.test(String(response.nextCursor))||BigInt(response.nextCursor)<BigInt(request.cursor)||BigInt(response.nextCursor)>9223372036854775807n)throw Error('invalid_preview_feed');
 nextCursor=String(response.nextCursor);items=response.items;
}else{
 if(response.insertionId!==request.insertionId||response.revision!==request.revision)throw Error('preview_identity_mismatch');
 if(response.publicationEnabled!==false||response.isPublicationEvidence!==false)throw Error('not_a_visual_preview');
 if(response.status!=='completed')return [{json:{ready:false,status:response.status,insertionId:request.insertionId,revision:request.revision,nextCursor:null,publicationEnabled:false},pairedItem:{item:0}}];
 items=[response];
}
if(response.publicationEnabled!==false)throw Error('publication_must_be_disabled');
if(!items.length)return [{json:{ready:false,status:'empty',nextCursor,publicationEnabled:false},pairedItem:{item:0}}];
return items.map(preview=>{
 if(!Number.isSafeInteger(preview.insertionId)||preview.insertionId<=0||!/^[A-Za-z0-9_-]{1,128}$/.test(preview.revision)||preview.status!=='completed'||preview.publicationEnabled!==false||preview.isPublicationEvidence!==false||preview.contentType!=='image/png'||!/^[a-f0-9]{64}$/.test(preview.sha256))throw Error('invalid_completed_preview');
 return {json:{ready:true,insertionId:preview.insertionId,revision:preview.revision,sha256:preview.sha256,nextCursor,path:'/api/insertions/'+preview.insertionId+'/visual-previews/'+preview.revision+'/download',caption:'PRÉVIA NÃO PUBLICADA — revisão '+preview.revision,publicationEnabled:false,isPublicationEvidence:false},pairedItem:{item:0}};
});

const result=[];
for(let index=0;index<$input.all().length;index++){
 const item=$input.all()[index],context=$('Prepare PNG downloads').itemMatching(index).json;
 const bytes=await this.helpers.getBinaryDataBuffer(index,'preview');
 if(!bytes||bytes.length<8||!bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))throw Error('invalid_png_response');
 if(!item.binary?.preview)throw Error('missing_preview_binary');
 item.binary.preview.mimeType='image/png';item.binary.preview.fileName='previa-'+context.insertionId+'-'+context.revision+'.png';
 const {path,...metadata}=context;
 result.push({json:metadata,binary:{preview:item.binary.preview},pairedItem:{item:index}});
}
return result;

return $input.all().map((item,index)=>{
 const original=$('Return PNG with revision').itemMatching(index);
 if(item.json.computedDigest!==original.json.sha256)throw Error('preview_checksum_mismatch');
 return {json:original.json,binary:original.binary,pairedItem:{item:index}};
});
